CREATE TABLE IF NOT EXISTS trips(id INTEGER PRIMARY KEY AUTOINCREMENT,status TEXT,launch_at INTEGER,created INTEGER,outcome TEXT,end_at INTEGER);
CREATE TABLE IF NOT EXISTS seats(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,name TEXT,tier TEXT,msg TEXT,status TEXT,trip_id INTEGER,ip TEXT,amount INTEGER,created INTEGER,paid_at INTEGER,fate TEXT,loc TEXT,rescued_by TEXT,rescued_at INTEGER,used INTEGER);
CREATE TABLE IF NOT EXISTS tx(id TEXT PRIMARY KEY,amount INTEGER,content TEXT,matched INTEGER DEFAULT 0,at INTEGER);
CREATE INDEX IF NOT EXISTS i_seats ON seats(trip_id,status);
